"use client";

import Link from "next/link";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui";
import { Badge } from "@/components/ui/badge";
import { PageHeader } from "@/components/layouts";
import { useAuth } from "@/auth";
import {
  mockOrders,
  orderStatusLabel,
  orderStatusVariant,
} from "../data/mock-data";

/**
 * Customer orders list (skill: Customer Dashboard - S3 Orders).
 *
 * Owner-scoped (skill S9 rule 3): only the current user orders show.
 * Each row links to /account/orders/[id].
 */
export function OrdersList() {
  const { user } = useAuth();
  const orders = mockOrders
    .filter((o) => o.ownerId === user?.id)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="space-y-4">
      <PageHeader
        title="سفارش‌ها"
        description="لیست تمام سفارش‌های ثبت‌شده شما"
      />
      <Card>
        <CardHeader>
          <CardTitle>تاریخچه سفارش‌ها</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="divide-y">
            {orders.map((order) => (
              <Link
                key={order.id}
                href={`/account/orders/${order.id}`}
                className="flex items-center gap-4 py-3 transition-colors hover:bg-muted/40 -mx-6 px-6"
              >
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img
                  src={order.productImage}
                  alt={order.productName}
                  className="h-12 w-12 shrink-0 rounded-lg border object-cover"
                />
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-medium">{order.productName}</p>
                  <p className="truncate text-xs text-muted-foreground">
                    {order.tenantName} · {new Date(order.date).toLocaleDateString("fa-IR")}
                  </p>
                </div>
                <Badge variant={orderStatusVariant[order.status]} className="shrink-0">
                  {orderStatusLabel[order.status]}
                </Badge>
              </Link>
            ))}
            {orders.length === 0 && (
              <p className="py-8 text-center text-sm text-muted-foreground">
                سفارشی ثبت نشده است.
              </p>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}
